
/* jsPDF offline stub - implements features used in this app */
(function(global) {
  'use strict';

  function jsPDF(opts) {
    opts = opts || {};
    this.orientation = opts.orientation || 'portrait';
    this.unit = opts.unit || 'mm';
    this.format = opts.format || 'a4';
    this._pages = [[]];
    this._currentPage = 0;
    this._fontSize = 10;
    this._fontStyle = 'normal';
    this._fontName = 'helvetica';
    this._textColor = '#000000';
    this.internal = {
      pageSize: { getWidth: () => 210, getHeight: () => 297 }
    };
    // A4 dimensions in mm
    this.pageWidth = 210;
    this.pageHeight = 297;
    this._elements = []; // store drawing commands
  }

  jsPDF.prototype.setFontSize = function(size) {
    this._fontSize = size;
    return this;
  };

  jsPDF.prototype.setFont = function(name, style) {
    this._fontName = name;
    this._fontStyle = style || 'normal';
    return this;
  };

  jsPDF.prototype.setTextColor = function(r, g, b) {
    if (typeof r === 'string') {
      this._textColor = r;
    } else {
      this._textColor = `rgb(${r},${g||0},${b||0})`;
    }
    return this;
  };

  jsPDF.prototype.setFillColor = function(r, g, b) {
    this._fillColor = typeof r === 'string' ? r : `rgb(${r},${g||0},${b||0})`;
    return this;
  };

  jsPDF.prototype.setDrawColor = function(r, g, b) {
    this._drawColor = typeof r === 'string' ? r : `rgb(${r},${g||0},${b||0})`;
    return this;
  };

  jsPDF.prototype.setLineWidth = function(w) {
    this._lineWidth = w;
    return this;
  };

  jsPDF.prototype.text = function(text, x, y, opts) {
    this._elements.push({type:'text', text: Array.isArray(text) ? text.join('\n') : String(text),
      x, y, fontSize: this._fontSize, fontStyle: this._fontStyle, color: this._textColor});
    return this;
  };

  jsPDF.prototype.splitTextToSize = function(text, maxWidth) {
    // Simple word wrap approximation (chars per line based on font size)
    const charsPerLine = Math.floor(maxWidth / (this._fontSize * 0.35));
    const words = String(text).split(' ');
    const lines = [];
    let line = '';
    for (const word of words) {
      if ((line + ' ' + word).length > charsPerLine && line) {
        lines.push(line.trim());
        line = word;
      } else {
        line += (line ? ' ' : '') + word;
      }
    }
    if (line) lines.push(line.trim());
    return lines;
  };

  jsPDF.prototype.rect = function(x, y, w, h, style) {
    this._elements.push({type:'rect', x, y, w, h, style});
    return this;
  };

  jsPDF.prototype.line = function(x1, y1, x2, y2) {
    this._elements.push({type:'line', x1, y1, x2, y2});
    return this;
  };

  jsPDF.prototype.addPage = function() {
    this._pages.push([]);
    this._currentPage++;
    return this;
  };

  jsPDF.prototype.save = function(filename) {
    // Generate HTML representation and print/save as PDF
    this._generateAndDownload(filename);
    return this;
  };

  jsPDF.prototype._generateAndDownload = function(filename) {
    // Build HTML content from elements for printing
    let html = `<!DOCTYPE html><html><head><meta charset="UTF-8">
<title>${filename}</title>
<style>
  body { font-family: Helvetica, Arial, sans-serif; margin: 0; padding: 20px; font-size: 10pt; color: #000; }
  .page { width: 210mm; min-height: 297mm; margin: 0 auto 20px; padding: 14mm; box-sizing: border-box; page-break-after: always; background: white; box-shadow: 0 2px 8px rgba(0,0,0,0.15); }
  table { width: 100%; border-collapse: collapse; margin: 8px 0; font-size: 9pt; }
  th { background: rgba(160,32,80,0.15); padding: 6px; border: 1px solid #c080a0; font-weight: bold; text-align: left; }
  td { border: 1px solid #e0b0c0; padding: 5px; }
  tr:nth-child(even) td { background: #fff8fb; }
  h1 { font-size: 16pt; color: #7a1040; margin-bottom: 4px; }
  h2 { font-size: 13pt; color: #9c1a50; margin: 12px 0 4px; }
  h3 { font-size: 11pt; color: #a02050; margin: 8px 0 3px; }
  .label { font-size: 9pt; font-weight: bold; color: #333; }
  .value { border-bottom: 1px solid #999; min-height: 18px; padding: 2px 4px; display: inline-block; min-width: 120px; font-size: 10pt; }
  .info-row { display: flex; gap: 20px; margin-bottom: 8px; flex-wrap: wrap; }
  .info-item { flex: 1; min-width: 120px; }
  p { margin: 4px 0; font-size: 10pt; line-height: 1.5; }
  @media print { body { padding: 0; } .page { box-shadow: none; margin: 0; } }
</style></head><body>`;

    // Collect all text for meaningful PDF content
    html += this._buildPDFContent();
    html += `</body></html>`;

    const blob = new Blob([html], {type: 'text/html;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const win = window.open(url, '_blank');
    if (win) {
      win.onload = () => {
        setTimeout(() => { win.print(); }, 500);
      };
    } else {
      // fallback: direct download
      const a = document.createElement('a');
      a.href = url;
      a.download = filename.replace('.pdf', '.html');
      a.click();
    }
  };

  jsPDF.prototype._buildPDFContent = function() {
    // The autoTable plugin populates _tableData; use it if available
    if (this._pdfData) return this._pdfData;
    let html = '<div class="page">';
    for (const el of this._elements) {
      if (el.type === 'text') {
        const size = el.fontSize >= 14 ? 'h2' : el.fontSize >= 12 ? 'h3' : 'p';
        html += `<${size} style="color:${el.color}">${el.text.replace(/\n/g,'<br>')}</${size}>`;
      }
    }
    html += '</div>';
    return html;
  };

  // Expose as both named export and window global
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { jsPDF };
  } else {
    global.jsPDF = jsPDF;
    if (!global.window) global.window = global;
    // Also support: const { jsPDF } = window.jspdf
    global.jspdf = { jsPDF };
  }
})(typeof window !== 'undefined' ? window : this);
